import React, { useState, useEffect } from "react";
import "bootstrap/dist/css/bootstrap.min.css";
import { useNavigate } from "react-router-dom";
import private_api from "../../server/private_api";

const LecionaLista = () => {
  const [cursos, setCursos] = useState([]);
  const [loading, setLoading] = useState(true);
  const navigate = useNavigate();

  // Obtém o ID do professor do localStorage
  // Assumindo que após login, armazenamos tanto userId quanto professorId
  const professorId = localStorage.getItem("professorId");

  const fetchCursos = async () => {
    try {
      if (!professorId) {
        throw new Error("ID do professor não encontrado");
      }

      const resposta = await private_api.get(
        `/professores/${professorId}/listacursos`
      );

      if (resposta.status === 200) {
        // Formata as datas para exibição
        const cursosFormatados = resposta.data.map((curso) => ({
          ...curso,
          dataInicio: curso.dataInicio
            ? new Date(curso.dataInicio).toISOString().split("T")[0]
            : "",
          dataFim: curso.dataFim
            ? new Date(curso.dataFim).toISOString().split("T")[0]
            : "",
        }));

        setCursos(cursosFormatados);
      } else {
        console.error("Erro ao buscar cursos");
      }
    } catch (error) {
      console.error("Erro na requisição:", error);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchCursos();
  }, []);

  if (loading) {
    return (
      <div className="d-flex justify-content-center mt-5">Carregando...</div>
    );
  }

  if (!professorId) {
    return (
      <div className="d-flex justify-content-center mt-5">
        Professor não identificado. Por favor, faça login novamente.
      </div>
    );
  }

  return (
    <div
      className="container-fluid d-flex flex-column align-items-center"
      style={{
        backgroundColor: "#E7EFF4",
        minHeight: "100vh",
        padding: "20px",
      }}
    >
      <nav className="nav nav-tabs mb-3 bg-white p-2 w-75 d-flex justify-content-center">
        <a className="nav-link active" href="#">
          Cursos
        </a>
        <a
          className="nav-link"
          href="#"
          onClick={() => navigate("/professoraulas")}
        >
          Aulas
        </a>
        <a
          className="nav-link"
          href="#"
          onClick={() => navigate("/professoravaliacoes")}
        >
          Avaliações
        </a>
      </nav>

      <h2 className="mb-3 text-center">Lista de Cursos à lecionar</h2>

      {cursos.length === 0 ? (
        <div className="alert alert-info w-75 text-center">
          Nenhum curso atribuído a você no momento.
        </div>
      ) : (
        <table className="table table-bordered bg-white w-75">
          <thead>
            <tr>
              <th>Curso</th>
              <th>Nível</th>
              <th>Área</th>
              <th>Período</th>
              <th>Data de Início</th>
              <th>Data de Fim</th>
            </tr>
          </thead>
          <tbody>
            {cursos.map((curso) => (
              <tr key={curso.id}>
                <td>{curso.nome}</td>
                <td>{curso.nivel}</td>
                <td>{curso.area}</td>
                <td>{curso.periodo}</td>
                <td>{curso.dataInicio}</td>
                <td>{curso.dataFim}</td>
              </tr>
            ))}
          </tbody>
        </table>
      )}
    </div>
  );
};

export default LecionaLista;
